function lr_macro($d,$id,$parent,$role,$position){$n=B\Draft::block($id,$d['id'],$parent,'MACRO',$position);$n['metadata']=array('role'=>$role,'label'=>$id,'independent_children'=>true,'duration_days'=>14);$n['children_strategy']='PARALLEL_AVAILABLE';return $n;}
function lr_random($ids,$count=1){return array('strategy'=>'WEIGHTED_RANDOM','scope'=>'EXECUTION','candidates'=>$ids,'select_n'=>null,'draw_count'=>$count,'weights'=>array_fill_keys($ids,1),'order'=>'DEFINITION','algorithm_version'=>'EIPSI_RANDOM_V1');}
