$random=lr_macro($d,'LR_BLOCK_RANDOM',$root,'BLOCK_RANDOMIZATION',1);$random['schedule']['temporal_rule']=array('kind'=>'OFFSET','duration'=>array('kind'=>'ELAPSED','seconds'=>86400));$random['children_strategy']='WEIGHTED_RANDOM';$random['randomization']=lr_random(array('LR_BLOCK_B','LR_BLOCK_C'));$d['nodes'][]=$random;
